const PUBLICATIONS: Publication[] = [
  { citation: '<b>Anish Sathyanarayanan*</b>, <b>Aditya Nagarsekar*</b>, <b>Aarush Rathore*</b> (2026). <a href="https://arxiv.org/abs/2602.03994"><u>Bypassing the Rationale: Causal Auditing of Implicit Reasoning in Language Models</u></a> (Latent & Implicit Thinking @ ICLR 2026)', abstract: 'Chain-of-thought (CoT) prompting is widely used as a reasoning aid and is often treated as a transparency mechanism. Yet behavioral gains under CoT do not imply that the model\'s internal computation causally depends on the emitted reasoning text, i.e., models may produce fluent rationales while routing decision-critical computation through latent pathways. We introduce a causal, layerwise audit of CoT faithfulness based on activation patching. Our key metric, the CoT Mediation Index (CMI), isolates CoT-specific causal influence by comparing performance degradation from patching CoT-token hidden states against matched control patches. Across multiple model families (Phi, Qwen, DialoGPT) and scales, we find that CoT-specific influence is typically depth-localized into narrow "reasoning windows," and we identify bypass regimes where CMI is near-zero despite plausible CoT text. We further observe that models tuned explicitly for reasoning tend to exhibit stronger and more structured mediation than larger untuned counterparts, while Mixture-of-Experts models show more distributed mediation consistent with routing-based computation. Overall, our results show that CoT faithfulness varies substantially across models and tasks and cannot be inferred from behavior alone, motivating causal, layerwise audits when using CoT as a transparency signal.' },
  { citation: '<b>Karan Bania*</b>, <b>Soham Kalburgi*</b>, Manit Tanwar*, Dhruthi*, <b>Aditya Nagarsekar*</b>, <b>Harshvardhan Mestha*</b>, Naman Chibber*, Raj Deshmukh*, <b>Anish Sathyanarayanan*</b>, <b>Aarush Rathore*</b>, <b>Pratham Chheda*</b> (2026). <a href="https://arxiv.org/abs/2602.08810"><u>lrnnx: A library for Linear RNNs</u></a> (SRW @ EACL 2026)', abstract: 'Linear recurrent neural networks (LRNNs) provide a structured approach to sequence modeling that bridges classical linear dynamical systems and modern deep learning, offering both expressive power and theoretical guarantees on stability and trainability. In recent years, multiple LRNN-based architectures have been proposed, each introducing distinct parameterizations, discretization schemes, and implementation constraints. However, existing implementations are fragmented across different software frameworks, often rely on framework-specific optimizations, and in some cases require custom CUDA kernels or lack publicly available code altogether. As a result, using, comparing, or extending LRNNs requires substantial implementation effort. To address this, we introduce lrnnx, a unified software library that implements several modern LRNN architectures under a common interface. The library exposes multiple levels of control, allowing users to work directly with core components or higher-level model abstractions. lrnnx aims to improve accessibility, reproducibility, and extensibility of LRNN research and applications. We make our code available under a permissive MIT license.' },
  { citation: 'Riya Singha, Aryan Amit Barsainyana, Rida Irfan, Connor Joseph Amorin, Stewart He, Tony Davis, Arun Thiagarajan, Shiva Sankaran, Seyone Chithrananda, Walid Ahmada, Derek Jones, Kevin McLoughlin, Hyojin Kim, Anoushka Bhutani, <b>Shreyas Vinaya Sathyanarayana</b>, Venkat Viswanathan, Jonathan E. Allen, Bharath Ramsundar (2025). <a href="https://chemrxiv.org/engage/api-gateway/chemrxiv/assets/orp/resource/item/688b04ca23be8e43d6fe2c69/original/chem-ber-ta-3-an-open-source-training-framework-for-chemical-foundation-models.pdf"><u>ChemBERTa-3: An open-source training framework for chemical foundation models</u></a>', abstract: 'The rapid advancement of machine learning in computational chemistry has opened new doors for designing molecules, predicting molecular properties, and discovering novel materials. How- ever, building scalable and robust models for molecular machine learning remains a significant challenge due to the vast size and complexity of chemical space. Recent advances in chemical foundation models hold considerable promise for addressing these challenges, but such models remain difficult to train and are often fully or partially proprietary. For this reason, we introduce ChemBERTa-3, an open source training and benchmarking framework designed to train and fine- tune large-scale chemical foundation models. ChemBERTa-3 provides: (i) unified, reproducible infrastructure for model pretraining and fine-tuning, (ii) systematic benchmarking tooling to evalu- ate proposed chemical foundation model architectures on tasks from the MoleculeNet suite, and (iii) fully open release of model weights, training configurations, and deployment workflows. Our experiments demonstrate that although both graph-based and transformer-based architectures perform well at small scale, transformer-based models are considerably easier to scale. We also discuss how to overcome the numerous challenges that arise when attempting to reproducibly construct large chemical foundation models, ranging from subtle benchmarking issues to training instabilities. We test ChemBERTa-3 infrastructure in both an AWS-based Ray deployment and in an on-premise high-performance computing cluster to verify the reproducibility of the frame- work and results. We anticipate that ChemBERTa-3 will serve as a foundational building block for next-generation chemical foundation models and for the broader project of creating open source LLMs for scientific applications. In support of reproducible and extensible science, we have open sourced all ChemBERTa3 models and our Ray cluster configurations.' },
  { citation: '<b>Shreyas Vinaya Sathyanarayana*</b>, Sharanabasava D. Hiremath* (et al.). (2025). <a href="https://arxiv.org/pdf/2507.07060"><u>DeepRetro: Retrosynthetic Pathway Discovery using Iterative LLM Reasoning</u></a>', abstract: 'The synthesis of complex natural products remains one of the grand challenges of organic chemistry. We present DeepRetro, a major advancement in com- putational retrosynthesis that enables the discovery of viable synthetic routes for complex molecules typically considered beyond the reach of existing ret- rosynthestic methods. DeepRetro is a novel, open-source framework that tightly integrates large language models (LLMs), traditional retrosynthetic engines, and expert human feedback in an iterative design loop. Prior approaches rely solely on template-based methods or unconstrained LLM outputs. In contrast, DeepRetro combines the precision of template-based methods with the generative flexibil- ity of LLMs, controlled by rigorous chemical validity checks and enhanced by recursive refinement. This hybrid system dynamically explores and revises syn- thetic pathways, guided by both algorithmic checks and expert chemist feedback through an interactive user interface. While DeepRetro achieves strong perfor- mance on standard retrosynthesis benchmarks, its true strength lies in its ability to propose novel, viable pathways to highly complex natural products—targets that have historically eluded automated planning. Through detailed case studies, we illustrate how this approach enables new routes for total synthesis and facili- tates human-machine collaboration in organic chemistry. Beyond retrosynthesis, DeepRetro represents a working model for how to leverage LLMs in scientific discovery. We provide a transparent account of the system\'s design, algorithms, and human-feedback loop, enabling broad adaptation across scientific domains. By releasing DeepRetro as an open-source tool, we aim to empower chemists to tackle increasingly ambitious synthetic targets, accelerating progress in drug discovery, materials design, and beyond.' },
  { citation: '<b>Karan Bania*</b>, <b>Harshvardhan Mestha*</b>, Tanmay Tulsidas Verlekar. (2025). <a href="https://ceur-ws.org/Vol-3985/paper4.pdf"><u>Exploring the Missing Medical Context in Generated Radiology Reports</u></a>', abstract: 'Recent advancements in multimodal LLMs have allowed its use in radiology, where, given an X-ray image, the report can be generated automatically. The state-of-the-art explores LLMs for this task through prompting or fine-tuning. The emphasis in such cases is to improve the syntax and context of the report with respect to natural language. This paper proposes that LLMS are unable to understand the medical context in images and in reports. Thus, the accuracy of the generated reports\' medical context requires further evaluation. This paper uses a pre-trained GPT-4o, Qwen2-VL-7B, and a fine-tuned LLaMA-2 model to demonstrate that these LLMs can identify the input images as chest X-rays but are poor at identifying pathologies, even when fine-tuned. It then attempts to address this problem by proposing a pipeline that allows the LLMs access to a discriminative model that can classify pathologies present in a chest X-ray. The additional context of pathology labels allows the LLMs to generate more accurate reports. A second contribution of the paper involves the assessment of the generated reports. It illustrates that traditional metrics, such as the BERTScore, are ineffective in assessing generated medical reports. It then presents an LLM-as-a-judge that successfully compares generated and ground truth reports.' },
  { citation: '<b>Ankita Vaishnobi Bisoi</b>, <b>Shreyas V.</b>, Jose Siguenza, Bharath Ramsundar. (2025). <a href="https://openreview.net/pdf?id=jWZV6hWCeX"><u>DeepChem-Variant: A Modular Open Source Framework for Genomic Variant Calling</u></a>', abstract: 'Variant calling is a fundamental task in genomic research for detecting genetic variations such as single nucleotide polymorphisms (SNPs) and in- sertions or deletions (indels). This paper presents an enhancement to DeepChem (Ramsundar et al., 2019), a widely used open source drug discov- ery framework, through the integration of Deep- Variant (Poplin et al., 2018). We introduce DeepChem-Variant, a variant calling pipeline that leverages DeepVariant\'s convolutional neural net- work (CNN) architecture to improve variant detec- tion accuracy and reliability. DeepChem-Variant has stages for realignment of sequencing reads, candidate variant detection, and pileup image generation, followed by variant classification us- ing either the original modified Inception V3 model or our novel MobileNetV2 implementa- tion. We performed 3 case studies to validate our approach. Our work also contributes opti- mized utility functions for genomic data formats, including enhanced DataLoaders for BAM, SAM, and CRAM files, and an optimized FASTALoader. These implementations collectively provide a modular and extensible variant calling framework within DeepChem, enabling tighter integration of DeepChem\'s drug discovery infrastructure with bioinformatics pipelines for future research.' },
  { citation: '<b>Harshvardhan Mestha*</b>, <b>Karan Bania*</b>, <b>Shreyas Vinaya Sathyanarayana</b>, Sidong Liu, Ashwin Srinivasan. (2025). <a href="https://arxiv.org/pdf/2410.20600?"><u>Multi-Turn Human–LLM Interaction Through the Lens of a Two-Way Intelligibility Protocol</u></a>', abstract: 'Our interest is in the design of software systems involving a human-expert interacting-using natural language-with a large language model (LLM) on data analysis tasks. For complex problems, it is possible that LLMs can harness human expertise and creativity to find solutions that were otherwise elusive. On one level, this interaction takes place through multiple turns of prompts from the human and responses from the LLM. Here we investigate a more structured approach based on an abstract protocol described in [3] for interaction between agents. The protocol is motivated by a notion of “two-way intelligibility” and is modelled by a pair of communicating finite-state machines. We provide an implementation of the protocol, and provide empirical evidence of using the implementation to mediate interactions between an LLM and a human-agent in two areas of scientific interest (radiology and drug design). We conduct controlled experiments with a human proxy (a database), and uncontrolled experiments with human subjects. The results provide evidence in support of the protocol\'s capability of capturing one- and two-way intelligibility in human-LLM interaction; and for the utility of two-way intelligibility in the design of human-machine systems. Our code is available at https://github.com/karannb/interact.' },
  { citation: 'Debasish Mohanty, <b>V. Shreyas</b>, Akshaya Palai, Bharath Ramsundar. (2024). <a href="https://arxiv.org/pdf/2412.08658"><u>Open-source Polymer Generative Pipeline</u></a>', abstract: 'Polymers play a crucial role in the development of engi- neering materials, with applications ranging from mechan- ical to biomedical fields. However, the limited polymer- ization processes constrain the variety of organic building blocks that can be experimentally tested. We propose an open-source computational generative pipeline that integrates neural-network-based discriminators, generators, and query- based filtration mechanisms to overcome this limitation and generate hypothetical polymers. The pipeline targets proper- ties, such as ionization potential (IP), by aligning various rep- resentational formats to generate hypothetical polymer can- didates. The discriminators demonstrate improvements over state-of-the-art models due to optimized architecture, while the generators produce novel polymers tailored to the desired property range. We conducted extensive evaluations to assess the generative performance of the pipeline components, fo- cusing on the polymers\' ionization potential (IP). The devel- oped pipeline is integrated into the DeepChem framework, enhancing its accessibility and compatibility for various poly- mer generation studies.' },
  { citation: '<b>V. Shreyas</b>, Jose Siguenza, <b>Karan Bania</b>, Bharath Ramsundar. (2024). <a href="https://arxiv.org/pdf/2408.06261?"><u>Open-Source Molecular Processing Pipeline for Generating Molecules</u></a>', abstract: 'Generative models for molecules have shown considerable promise for use in computational chemistry, but remain difficult to use for non-experts. For this reason, we introduce open-source infrastructure for easily building generative molecular models into the widely used DeepChem [25] library with the aim of creating a robust and reusable molecular generation pipeline. In particular, we add high quality PyTorch [20] implementations of the Molecular Generative Adversarial Networks (MolGAN) [2] and Normalizing Flows [19]. Our implementations show strong performance comparable with past work [13, 2].' },
  { citation: '<b>Harshvardhan Mestha</b>, <b>Tejas Agrawal</b>, <b>Karan Bania</b>, <b>V. Shreyas</b>, <b>Yash Bhisikar</b>. (2024). <a href="https://arxiv.org/pdf/2406.03586"><u>CountCLIP — [Re] Teaching CLIP to Count to Ten</u></a>', abstract: 'Large vision-language models (VLMs) are shown to learn rich joint image-text rep- resentations enabling high performances in relevant downstream tasks. However, they fail to showcase their quantitative understanding of objects, and they lack good counting-aware representation. This paper conducts a reproducibility study of \'Teaching CLIP to Count to Ten\' [1], which presents a method to finetune a CLIP model [2] to improve zero-shot counting accuracy in an image while maintaining the performance for zero-shot classification by introducing a counting-contrastive loss term. We contribute to the existing methods by improving the model\'s performance on a smaller subset of their training data with lower computational resources. We verify these claims by reproducing their study with our own open-source code. The implementation can be found at https://github.com/SforAiDl/CountCLIP.' },
  { citation: 'Mark Schöne*, <b>Yash Bhisikar*</b>, <b>Karan Bania*</b>, Khaleelulla Khan Nazeer, Christian Mayr, Anand Subramoney, David Kappel. (2024). <a href="https://arxiv.org/pdf/2411.12603"><u>STREAM: A Universal State-Space Model for Sparse Geometric Data</u></a>', abstract: 'Handling sparse and unstructured geometric data, such as point clouds or event-based vision, is a pressing challenge in the field of machine vision. Recently, sequence models such as Transformers and state-space models entered the domain of geometric data. These methods require specialized preprocessing to create a sequential view of a set of points. Furthermore, prior works involving sequence models iterate geometric data with either uniform or learned step sizes, implicitly relying on the model to infer the underlying geometric structure. In this work, we propose to encode geometric structure explicitly into the parameterization of a state-space model. State-space models are based on linear dynamics governed by a one-dimensional variable such as time or a spatial coordinate. We exploit this dynamic variable to inject relative differences of coordinates into the step size of the state-space model. The resulting geometric operation computes interactions between all pairs of N points in O(N) steps. Our model deploys the Mamba selective state-space model with a modified CUDA kernel to efficiently map sparse geometric data to modern hardware. The resulting sequence model, which we call STREAM, achieves competitive results on a range of benchmarks from point-cloud classification to event-based vision and audio classification. STREAM demonstrates a powerful inductive bias for sparse geometric data by improving the PointMamba baseline when trained from scratch on the ModelNet40 and ScanObjectNN point cloud analysis datasets. It further achieves, for the first time, 100 % test accuracy on all 11 classes of the DVS128 Gestures dataset.' },
  { citation: '<b>Bhisikar, Yash</b>; Govindaraj, Nirmal; Devaki, Venkatavihan; Anilkumar, Ritu. (2024). <a href="https://ui.adsabs.harvard.edu/abs/2024EGUGA..2619531B/abstract"><u>Gradient-Based Optimisers Versus Genetic Algorithms in Deep Learning Architectures</u></a>', abstract: 'Gradient-Based Optimisers Versus Genetic Algorithms in Deep Learning Architectures:A Case Study on Rainfall Estimation Over Complex Terrain Yash Bhisikar1*, Nirmal Govindaraj1*, Venkatavihan Devaki2*, Ritu Anilkumar31Birla Institute of Technology And Science, Pilani, K K Birla Goa Campus 2Birla Institute of Technology And Science, Pilani, Pilani Campus 3North Eastern Space Applications Centre, Department of Space, UmiamE-mail: f20210483@goa.bits-pilani.ac.in* Authors have contributed equally to this study.Rainfall is a crucial factor that affects planning processes at various scales, ranging from agricultural activities at the village or residence level to governmental initiatives in the domains of water resource management, disaster preparedness, and infrastructural planning. Thus, a reliable estimate of rainfall and a systematic assessment of variations in rainfall patterns is the need of the hour. Recently, several studies have attempted to predict rainfall over various locations using deep learning architectures, including but not limited to artificial neural networks, convolutional neural networks, recurrent neural networks, or a combination of these. However, a major challenge in the estimation of rainfall is the chaotic nature of rainfall, especially the interplay of spatio-temporal components over orographically complex terrain. For complex computer vision challenges, studies have suggested that population search-driven optimisation techniques such as genetic algorithms may be used in the optimisation as an alternative to traditional gradient-based techniques such as Adam, Adadelta and SGD. Through this study, we aim to extend this hypothesis to the case of rainfall estimation. We integrate the use of population search-based techniques, namely genetic algorithms, to optimise a convolutional neural network architecture built using PyTorch. We have chosen the study area of North-East India for this study as it receives significant monsoon rainfall and is impacted by the undulating terrain that adds complexity to the rainfall estimation. We have used 30 years of rainfall data from the ERA5 Land daily reanalysis dataset with a spatial resolution of 11,132 m for the months of June, July, August and September. Additionally, datasets of the following meteorological variables that can impact rainfall were utilised as input features: dew point temperature, skin temperature, net incoming short-wave radiation received at the surface, wind components and surface pressure. All the datasets are aggregated to daily time steps. Several configurations of the U-Net architecture, such as the number of hidden layers, initialisation techniques and optimisation algorithms, have been used to identify the best configuration in the estimation of rainfall for North-East India. Genetic algorithms were used in initialisation and optimisation to assess the ability of population search heuristics using the PyGAD library. The developed rainfall prediction models were validated at different time steps (0-day, 1-day, 2-day and 3-day latency) on a 7:1:2 train, validation, test dataset split for evaluation metrics such as root mean square error (RMSE) and coefficient of determination (R-squared). The evaluation was performed on a pixel-by-pixel basis as well as an image-by-image basis in order to take magnitude and spatial correlations into consideration. Our study emphasises the importance of considering alternate optimising functions and hyperparameter tuning approaches for complex earth observation challenges such as rainfall prediction.' },
  { citation: '<b>Ashmit Khandelwal</b>, <b>Aditya Agrawal</b>, Aanisha Bhattacharyya, Yaman K Singla, <b>Somesh Singh</b>, Uttaran Bhattacharya, Ishita Dasgupta, Stefano Petrangeli, Rajiv Ratn Shah, Changyou Chen, Balaji Krishnamurthy. (2024). <a href="https://arxiv.org/abs/2309.00359"><u>Large Content And Behavior Models To Understand, Simulate, And Optimize Content And Behavior</u></a> - [ICLR 2024 - Spotlight]', abstract: 'Shannon, in his seminal paper introducing information theory, divided the communication into three levels: technical, semantic, and effectivenss. While the technical level is concerned with accurate reconstruction of transmitted symbols, the semantic and effectiveness levels deal with the inferred meaning and its effect on the receiver. Thanks to telecommunications, the first level problem has produced great advances like the internet. Large Language Models (LLMs) make some progress towards the second goal, but the third level still remains largely untouched. The third problem deals with predicting and optimizing communication for desired receiver behavior. LLMs, while showing wide generalization capabilities across a wide range of tasks, are unable to solve for this. One reason for the underperformance could be a lack of "behavior tokens\'\' in LLMs\' training corpora. Behavior tokens define receiver behavior over a communication, such as shares, likes, clicks, purchases, retweets, etc. While preprocessing data for LLM training, behavior tokens are often removed from the corpora as noise. Therefore, in this paper, we make some initial progress towards reintroducing behavior tokens in LLM training. The trained models, other than showing similar performance to LLMs on content understanding tasks, show generalization capabilities on behavior simulation, content simulation, behavior understanding, and behavior domain adaptation. Using a wide range of tasks on two corpora, we show results on all these capabilities. We call these models Large Content and Behavior Models (LCBMs). Further, to spur more research on LCBMs, we release our new Content Behavior Corpus (CBC), a repository containing communicator, message, and corresponding receiver behavior.' },
  { citation: 'Victor Boutin, Thomas Fel, Lakshya Singhal, <b>Rishav Mukherji</b>, Akash Nagaraj, Julien Colin, Thomas Serre (2023). <a href="https://arxiv.org/abs/2301.11722"><u>Diffusion Models as Artists: Are we Closing the Gap between Humans and Machines?</u></a> - [ICML 2023 - Oral Presentation]', abstract: 'An important milestone for AI is the development of algorithms that can produce drawings that are indistinguishable from those of humans. Here, we adapt the \'diversity vs. recognizability\' scoring framework from Boutin et al, 2022 and find that one-shot diffusion models have indeed started to close the gap between humans and machines. However, using a finer-grained measure of the originality of individual samples, we show that strengthening the guidance of diffusion models helps improve the humanness of their drawings, but they still fall short of approximating the originality and recognizability of human drawings. Comparing human category diagnostic features, collected through an online psychophysics experiment, against those derived from diffusion models reveals that humans rely on fewer and more localized features. Overall, our study suggests that diffusion models have significantly helped improve the quality of machine-generated drawings; however, a gap between humans and machines remains -- in part explainable by discrepancies in visual strategies.' },
  { citation: '<b>S I Harini</b>, Gautam Shroff, Ashwin Srinivasan, Prayushi Faldu, Lovekesh Vig (2023). <a href="https://arxiv.org/abs/2302.08996"><u>Neuro-symbolic Meta Reinforcement Learning for Trading</u></a> - [AAAI 2023 Workshop on Multimodal AI for Financial Forecasting]', abstract: 'We model short-duration (e.g. day) trading in financial markets as a sequential decision-making problem under uncertainty, with the added complication of continual concept-drift. We, therefore, employ meta reinforcement learning via the RL2 algorithm. It is also known that human traders often rely on frequently occurring symbolic patterns in price series. We employ logical program induction to discover symbolic patterns that occur frequently as well as recently, and explore whether using such features improves the performance of our meta reinforcement learning algorithm. We report experiments on real data indicating that meta-RL is better than vanilla RL and also benefits from learned symbolic features.' },
  { citation: 'Shounak Naik, <b>Rajaswa Patil</b>, Swati Agrawal, Veeky Baths (2022). <a href="https://arxiv.org/abs/2207.07706"><u>Probing Semantic Grounding in Language Models of Code with Representational Similarity Analysis</u></a> - [18th ADMA]', abstract: 'Representational Similarity Analysis is a method from cognitive neuroscience, which helps in comparing representations from two different sources of data. In this paper, we propose using Representational Similarity Analysis to probe the semantic grounding in language models of code. We probe representations from the CodeBERT model for semantic grounding by using the data from the IBM CodeNet dataset. Through our experiments, we show that current pre-training methods do not induce semantic grounding in language models of code, and instead focus on optimizing form-based patterns. We also show that even a little amount of fine-tuning on semantically relevant tasks increases the semantic grounding in CodeBERT significantly. Our ablations with the input modality to the CodeBERT model show that using bimodal inputs (code and natural language) over unimodal inputs (only code) gives better semantic grounding and sample efficiency during semantic fine-tuning. Finally, our experiments with semantic perturbations in code reveal that CodeBERT is able to robustly distinguish between semantically correct and incorrect code.' },
  { citation: 'Ramit Sawhney*, Ritesh Singh Soun*, <b>Shrey Pandit</b>*, Megh Thakkar*, Sarvagya Malaviya, Yuval Pinter (2022). <a href="https://aclanthology.org/2022.naacl-main.127.pdf"><u>CIAug: Equipping Interpolative Augmentation with Curriculum Learning</u></a> - [NAACL 2022 - Main Conference]', abstract: 'Interpolative data augmentation has proven to be effective for NLP tasks. Despite its merits, the sample selection process in mixup is random, which might make it difficult for the model to generalize better and converge faster. We propose CIAug, a novel curriculum-based learning method that builds upon mixup. It leverages the relative position of samples in hyperbolic embedding space as a complexity measure to gradually mix up increasingly difficult and diverse samples along training. CIAug achieves state-of-the-art results over existing interpolative augmentation methods on 10 benchmark datasets across 4 languages in text classification and named-entity recognition tasks. It also converges and achieves benchmark F1 scores 3 times faster. We empirically analyze the various components of CIAug, and evaluate its robustness against adversarial attacks.' },
  { citation: 'Ramit Sawhney*, Megh Thakkar*, <b>Shrey Pandit</b>*, Ritesh Singh Soun, Di Jin, Diyi Yang, Lucie Flek (2022). <a href="https://faculty.cc.gatech.edu/~dyang888/docs/acl22_dmix.pdf"><u>DMix: Adaptive Distance-aware Interpolative Mixup</u></a> - [ACL 2022 - Main Conference]', abstract: 'Interpolation-based regularisation methods such as Mixup, which generate virtual training samples, have proven to be effective for various tasks and modalities. We extend Mixup and propose DMIX, an adaptive distance-aware interpolative Mixup that selects samples based on their diversity in the embedding space. DMIX leverages the hyperbolic space as a similarity measure among input samples for a richer encoded representation. DMIX achieves state-of-the-art results on sentence classification over existing data augmentation methods on 8 benchmark datasets across English, Arabic, Turkish, and Hindi languages while achieving benchmark F1 scores in 3 times less number of iterations. We probe the effectiveness of DMIX in conjunction with various similarity measures and qualitatively analyze the different components. DMIX being generalizable, can be applied to various tasks, models and modalities.' },
  { citation: 'Swapnil Parekh*, Yaman Singla Kumar*, <b>Somesh Singh</b>*, Changyou Chen, Balaji Krishnamurthy, Rajiv Ratn Shah (2021). <a href="https://arxiv.org/abs/2109.12406"><u>MINIMAL: Mining Models for Data Free Universal Adversarial Triggers</u></a> [AAAI 2022]', abstract: 'It is well known that natural language models are vulnerable to adversarial attacks, which are mostly input-specific in nature. Recently, it has been shown that there also exist input-agnostic attacks in NLP models, called universal adversarial triggers. However, existing methods to craft universal triggers are data intensive. They require large amounts of data samples to generate adversarial triggers, which are typically inaccessible by attackers. For instance, previous works take 3000 data samples per class for the SNLI dataset to generate adversarial triggers. In this paper, we present a novel data-free approach, MINIMAL, to mine input-agnostic adversarial triggers from models. Using the triggers produced with our data-free algorithm, we reduce the accuracy of Stanford Sentiment Treebank\'s positive class from 93.6% to 9.6%. Similarly, for the Stanford Natural Language Inference (SNLI), our single-word trigger reduces the accuracy of the entailment class from 90.95% to less than 0.6\\%. Despite being completely data-free, we get equivalent accuracy drops as data-dependent methods.' },
  { citation: 'Gaurav Kumar Nayak, <b>Het Shah</b>, Anirban Chakraborty (2021). <a href="https://arxiv.org/abs/2110.13598"><u>Incremental Learning for Animal Pose Estimation using RBF k-DPP</u></a> - [BMVC 2021]', abstract: 'Pose estimation is the task of locating keypoints for an object of interest in an image. Animal Pose estimation is more challenging than estimating human pose due to high inter and intra class variability in animals. Existing works solve this problem for a fixed set of predefined animal categories. Models trained on such sets usually do not work well with new animal categories. Retraining the model on new categories makes the model overfit and leads to catastrophic forgetting. Thus, in this work, we propose a novel problem of “Incremental Learning for Animal Pose Estimation”. Our method uses an exemplar memory, sampled using Determinantal Point Processes (DPP) to continually adapt to new animal categories without forgetting the old ones. We further propose a new variant of k-DPP that uses RBF kernel (termed as “RBF k-DPP”) which gives more gain in performance over traditional k-DPP. Due to memory constraints, the limited number of exemplars along with new class data can lead to class imbalance. We mitigate it by performing image warping as an augmentation technique. This helps in crafting diverse poses, which reduces overfitting and yields further improvement in performance. The efficacy of our proposed approach is demonstrated via extensive experiments and ablations where we obtain significant improvements over state-of-the-art baseline methods.' },
  { citation: '<b>Vedant Shah</b>, Gautam Shroff (2021). <a href="https://arxiv.org/abs/2110.10233"><u>Forecasting Market Prices using DL with Data Augmentation and Meta-learning: ARIMA still wins!</u></a> - [NeurIPS 2021 Workshop]', abstract: 'Deep-learning techniques have been successfully used for time-series forecasting and have often shown superior performance on many standard benchmark datasets as compared to traditional techniques. Here we present a comprehensive and comparative study of performance of deep-learning techniques for forecasting prices in financial markets. We benchmark state-of-the-art deep-learning baselines, such as NBeats, etc., on data from currency as well as stock markets. We also generate synthetic data using a fuzzy-logic based model of demand driven by technical rules such as moving averages, which are often used by traders. We benchmark the baseline techniques on this synthetic data as well as use it for data augmentation. We also apply gradient-based meta-learning to account for non-stationarity of financial time-series. Our extensive experiments notwithstanding, the surprising result is that the standard ARIMA models outperforms deep-learning even using data augmentation or meta-learning. We conclude by speculating as to why this might be the case.' },
  { citation: 'Souradeep Chakraborty, Rahul Bajpai, Naveen Gupta (2021). <b><u>R2D2D - Using Deep Learning for Caching in 5G D2D Communications</u></b> [IEEE VTC 21 Spring]', abstract: '' },
  { citation: 'Urvil Jivani, <b>Omatharv Vaidya</b>, Anwesh Bhattacharya, Snehanshu Saha (2021). <a href="https://arxiv.org/abs/2104.04795"><u>A Swarm Variant for the Schrödinger Solver</u></a> [IJCNN 2021]', abstract: 'This paper introduces application of the Exponentially Averaged Momentum Particle Swarm Optimization (EM-PSO) as a derivative-free optimizer for Neural Networks. It adopts PSO\'s major advantages such as search space exploration and higher robustness to local minima compared to gradient-descent optimizers such as Adam. Neural network based solvers endowed with gradient optimization are now being used to approximate solutions to Differential Equations. Here, we demonstrate the novelty of EM-PSO in approximating gradients and leveraging the property in solving the Schrödinger equation, for the Particle-in-a-Box problem. We also provide the optimal set of hyper-parameters supported by mathematical proofs, suited for our algorithm.' },
  { citation: 'Ramit Sawhney, Megh Thakkar, <b>Shrey Pandit</b>, Debdoot Mukherjee, and Lucie Flek (2021). <b><u>DMix: Distance Constrained Interpolative Mixup</u></b> [Extended Abstract, MRL Workshop, EMNLP 2021]', abstract: 'Interpolation-based regularisation methods have proven to be effective for various tasks and modalities. Mixup is a data augmentation method that generates virtual training samples from convex combinations of individual inputs and labels. We extend Mixup and propose, distance-constrained interpolative Mixup for sentence classification leveraging the hyperbolic space. This method achieves state-of-the-art results on sentence classification over existing data augmentation methods across datasets in four languages.' },
  { citation: '<b>Rajaswa Patil</b>, Jasleen Dhillon, Siddhant Mahurkar, Saumitra Kulkarni, Manav Malhotra, Veeky Baths (2021). <a href="https://rajaswa.github.io/publication/vyakarana-2021/"><u>Vyākarana: A Colorless Green Benchmark for Syntactic Evaluation in Indic Languages</u></a> [MRL Workshop, EMNLP 2021]', abstract: 'While there has been significant progress towards developing NLU resources for Indic languages, syntactic evaluation has been relatively less explored. Unlike English, Indic languages have rich morphosyntax, grammatical genders, free linear word-order, and highly inflectional morphology. In this paper, we introduce Vyākarana: a benchmark of Colorless Green sentences in Indic languages for syntactic evaluation of multilingual language models. The benchmark comprises four syntax-related tasks: PoS Tagging, Syntax Tree-depth Prediction, Grammatical Case Marking, and Subject-Verb Agreement. We use the datasets from the evaluation tasks to probe five multilingual language models of varying architectures for syntax in Indic languages. Due to its prevalence, we also include a code-switching setting in our experiments. Our results show that the token-level and sentence-level representations from the Indic language models (IndicBERT and MuRIL) do not capture the syntax in Indic languages as efficiently as the other highly multilingual language models. Further, our layer-wise probing experiments reveal that while mBERT, DistilmBERT, and XLM-R localize the syntax in middle layers, the Indic language models do not show such syntactic localization.' },
  { citation: 'Abheesht Sharma, Gunjan Chhablani, Harshit Pandey, <b>Rajaswa Patil</b> (2021). <a href="https://arxiv.org/abs/2107.01198"><u>DRIFT: A Toolkit for Diachronic Analysis of Scientific Literature</u></a> [Systems Demo, EMNLP 2021]', abstract: 'In this work, we present to the NLP community, and to the wider research community as a whole, an application for the diachronic analysis of research corpora. We open source an easy-to-use tool coined: DRIFT, which allows researchers to track research trends and development over the years. The analysis methods are collated from well-cited research works, with a few of our own methods added for good measure. Succinctly put, some of the analysis methods are: keyword extraction, word clouds, predicting declining/stagnant/growing trends using Productivity, tracking bi-grams using Acceleration plots, finding the Semantic Drift of words, tracking trends using similarity, etc. To demonstrate the utility and efficacy of our tool, we perform a case study on the cs.CL corpus of the arXiv repository and draw inferences from the analysis methods. The toolkit and the associated code are available here: this URL.' },
  { citation: '<b>Ajay Subramanian</b>, <b>Sharad Chitlangia</b>, Veeky Baths. (2021). <a href="https://arxiv.org/pdf/2007.01099.pdf"><u>Reinforcement Learning and its Connections with Neuroscience and Psychology</u></a> [Elsevier Neural Networks]', abstract: 'Reinforcement learning methods have been recently been very successful in complex sequential tasks like playing Atari games, Go and Poker. Through minimal input from humans, these algorithms are able to learn to perform complex tasks from scratch, just through interaction with their environment. While there certainly has been considerable independent innovation in the area, many core ideas in RL are inspired by animal learning and psychology. Moreover, these algorithms are now helping advance neuroscience research by serving as a computational model for many characteristic features of brain functioning. In this context, we review a number of findings that establish evidence of key elements of the RL problem and solution being represented in regions of the brain.' },
  { citation: '<b>Vedant Shah</b>, Anmol Agarwal, Tanmay Tulsidas Verlekar, Raghavendra Singh (2021). <a href="https://openaccess.thecvf.com/content/ICCV2021W/TradiCV/papers/Shah_Adapting_Deep_Neural_Networks_for_Pedestrian-Detection_to_Low-Light_Conditions_Without_ICCVW_2021_paper.pdf"><u>Adapting Deep Learning Models for Pedestrian-Detection to Low-Light Conditions without Re-training</u></a> [TradiCV Workshop, ICCV 2021]', abstract: 'Pedestrian detection is an integral component in many automated surveillance applications. Several state-of-theart systems exist for pedestrian detection, however most of them are ineffective in low-light conditions. Systems specifically designed for low-light conditions require special equipment, such as depth sensing cameras. However, a lack of large publicly available depth datasets, prevents their use in training deep learning models. In this paper we propose a pre-processing pipeline, which enables any existing normal-light pedestrian detection system to operate in low-light conditions. It is based on a signal-processing and traditional computer-vision techniques, such as the use of signal strength of a depth sensing camera (amplitude images) and robust principal component analysis (RPCA). The information in an amplitude image is less noisy, and is of lower dimension than depth data, marking it computationally inexpensive to process. RPCA processes these amplitude images to generate foreground masks, which represent potential regions of interest. These masks can then be used to rectify the RGB images to increase the contrast between the foreground and background, even in low-light conditions. We show that these rectified RGB images can be used by normal-light deep learning models for pedestrian-detection, without any additional training. To test this hypothesis, we use the ’Oyla Low-Light Pedestrian Benchmark’ (OLPB) dataset. Our results using two state-of-the art deep learning models (CrowdDet and CenterNet) show: a) The deep models perform poorly as pedestrian detectors in low-light conditions; b) Equipping the deep-networks with our pre-processing pipeline significantly improves the average precision for pedestriandetection of the models without any re-training. Taken together, the results suggest that our approach could act as a useful pre-processor for deep learning models that aren’t specially designed for pedestrian-detection in lowlight conditions.' },
  { citation: '<b>Pranav Mahajan</b>, Veeky Baths. (2021). <a href="https://www.frontiersin.org/articles/10.3389/fnagi.2021.623607/full"><u>Acoustic and Language Based Deep Learning Approaches for Alzheimer\'s Dementia Detection From Spontaneous Speech</u></a> [Frontiers in Aging Neuroscience]', abstract: '' },
  { citation: '<b>Mehul Rastogi</b>, Sen Lu, Nafiul Islam, Abhronil Sengupta. (2021). <a href="https://doi.org/10.3389/fnins.2020.603796"><u>On the Self-Repair Role of Astrocytes in STDP Enabled Unsupervised SNNs</u></a> [Frontiers in Neuroscience]', abstract: 'Neuromorphic computing is emerging to be a disruptive computational paradigm that attempts to emulate various facets of the underlying structure and functionalities of the brain in the algorithm and hardware design of next-generation machine learning platforms. This work goes beyond the focus of current neuromorphic computing architectures on computational models for neuron and synapse to examine other computational units of the biological brain that might contribute to cognition and especially self-repair. We draw inspiration and insights from computational neuroscience regarding functionalities of glial cells and explore their role in the fault-tolerant capacity of Spiking Neural Networks (SNNs) trained in an unsupervised fashion using Spike-Timing Dependent Plasticity (STDP). We characterize the degree of self-repair that can be enabled in such networks with varying degree of faults ranging from 50 to 90% and evaluate our proposal on the MNIST and Fashion-MNIST datasets.' },
  { citation: '<b>Ashwin Vaswani</b>*, <b>Rijul Ganguly</b>*, <b>Het Shah</b>*, Sharan Ranjit S.*, <b>Shrey Pandit</b>, Samruddhi Bothara. (2020). <b><u>Whatif Challenge: An Autoencoder Based Approach to Simulate Football Games</u></b> [7th Workshop on ML and Data Mining for Sports Analytics 2020]', abstract: '' },
  { citation: '<b>Rajaswa Patil</b>*, <b>Somesh Singh</b>*, Swati Agarwal. (2020). <a href="https://arxiv.org/abs/2006.00593"><u>BPGC at SemEval-2020 Task 11: Propaganda Detection in News Articles</u></a> [SemEval Workshop, COLING 2020]', abstract: 'Propaganda spreads the ideology and beliefs of like-minded people, brainwashing their audiences, and sometimes leading to violence. SemEval 2020 Task-11 aims to design automated systems for news propaganda detection. Task-11 consists of two sub-tasks, namely, Span Identification - given any news article, the system tags those specific fragments which contain at least one propaganda technique; and Technique Classification - correctly classify a given propagandist statement amongst 14 propaganda techniques. For sub-task 1, we use contextual embeddings extracted from pre-trained transformer models to represent the text data at various granularities and propose a multi-granularity knowledge sharing approach. For sub-task 2, we use an ensemble of BERT and logistic regression classifiers with linguistic features. Our results reveal that the linguistic features are the strong indicators for covering minority classes in a highly imbalanced dataset.' },
  { citation: 'Siddhant Mahurkar*, <b>Rajaswa Patil</b>*. (2020). <a href="https://arxiv.org/abs/2006.00607"><u>LRG at SemEval-2020 Task 7: Assessing the Ability of BERT and Derivative Models to Perform Short-Edits based Humor Grading</u></a> [SemEval Workshop, COLING 2020]', abstract: 'In this paper, we assess the ability of BERT and its derivative models (RoBERTa, DistilBERT, and ALBERT) for short-edits based humor grading. We test these models for humor grading and classification tasks on the Humicroedit and the FunLines dataset. We perform extensive experiments with these models to test their language modeling and generalization abilities via zero-shot inference and cross-dataset inference based approaches. Further, we also inspect the role of self-attention layers in humor-grading by performing a qualitative analysis over the self-attention weights from the final layer of the trained BERT model. Our experiments show that all the pre-trained BERT derivative models show significant generalization capabilities for humor-grading related tasks.' },
  { citation: '<b>Rajaswa Patil</b>*, Veeky Baths. (2020). <a href="https://arxiv.org/abs/2006.00609"><u>CNRL at SemEval-2020 Task 5: Modelling Causal Reasoning in Language with Multi-Head Self-Attention Weights</u></a> [SemEval Workshop, COLING 2020]', abstract: 'In this paper, we describe an approach for modelling causal reasoning in natural language by detecting counterfactuals in text using multi-head self-attention weights. We use pre-trained transformer models to extract contextual embeddings and self-attention weights from the text. We show the use of convolutional layers to extract task-specific features from these self-attention weights. Further, we describe a fine-tuning approach with a common base model for knowledge sharing between the two closely related sub-tasks for counterfactual detection. We analyze and compare the performance of various transformer models in our experiments. Finally, we perform a qualitative analysis with the multi-head self-attention weights to interpret our models\' dynamics.' },
  { citation: 'Srivatsan Krishnan*, <b>Sharad Chitlangia</b>*, Maximilian Lam*, Zishen Wan, Alexandra Faust, Vijay Janapa Reddi. (2020). <a href="https://arxiv.org/pdf/1910.01055.pdf"><u>Quantized Reinforcement Learning</u></a> [ReCoML Workshop, MLSys 2020]', abstract: 'Recent work has shown that quantization can help reduce the memory, compute, and energy demands of deep neural networks without significantly harming their quality. However, whether these prior techniques, applied traditionally to image-based models, work with the same efficacy to the sequential decision making process in reinforcement learning remains an unanswered question. To address this void, we conduct the first comprehensive empirical study that quantifies the effects of quantization on various deep reinforcement learning policies with the intent to reduce their computational resource demands. We apply techniques such as post-training quantization and quantization aware training to a spectrum of reinforcement learning tasks (such as Pong, Breakout, BeamRider and more) and training algorithms (such as PPO, A2C, DDPG, and DQN). Across this spectrum of tasks and learning algorithms, we show that policies can be quantized to 6-8 bits of precision without loss of accuracy. We also show that certain tasks and reinforcement learning algorithms yield policies that are more difficult to quantize due to their effect of widening the models\' distribution of weights and that quantization aware training consistently improves results over post-training quantization and oftentimes even over the full precision baseline. Finally, we demonstrate real-world applications of quantization for reinforcement learning. We use half-precision training to train a Pong model 50% faster, and we deploy a quantized reinforcement learning based navigation policy to an embedded system, achieving an 18×speedup and a 4× reduction in memory usage over an unquantized policy.' },
  { citation: '<b>Ajay Subramanian</b>*, <b>Rajaswa Patil</b>*, Veeky Baths. (2019). <b><u>Word2Brain2Image: Visual Reconstruction from Spoken Word Representations</u></b> [Poster, ACCS 2019]', abstract: 'Recent work in cognitive neuroscience has aimed to better understand how the brain responds to external stimuli. Extensive study is being done to gauge the involvement of various regions of the brain in the processing of external stimuli. A study by Ostarek et al. has produced experimental evidence of the involvement of low-level visual representations in spoken word processing, using Continuous Flash Suppression (CFS). For example, hearing the word ‘car’ induces a visual representation of a car in extrastriate areas of the visual cortex that seems to have a spatial resolution of some kind. Though the structure of these areas of the brain has been extensively studied, research hasn’t really delved into the functional aspects. In this work, we aim to take this a step further by experimenting with generative models such as Variational Autoencoders (VAEs) (Kingma et al 2013) and Generative Adversarial Networks (GANs) (Goodfellow et al. 2014) to generate images purely from the EEG signals induced by listening to spoken words of objects.' },
  { citation: '<b>Rajaswa Patil</b>*, Siddhant Mahurkar. (2019). <b><u>Citta: A Lite Semantic Recommendation Framework for Digital Libraries</u></b> [Best Student Poster Award, KEDL 2019]', abstract: 'Most of the recommendation and search frameworks in Digital Libraries follow a keyword-based approach to resolve text-based search queries. Keyword-based methods usually fail to capture the semantic aspects of the user’s query and often lead to a misleading set of results. In this work, we propose an efficient and content-sentiment aware semantic recommendation framework, Citta. The framework is designed with the BERT language model. It is designed to retrieve semantically related reading recommendations with short input queries and shorter response times. We test the proposed framework on the CMU Book Summary Dataset and discuss the observed advantages and shortcomings of the framework.' },
  { citation: '<b>Souradeep Chakroborty</b>. (2019). <a href="https://arxiv.org/abs/1907.04373"><u>Capturing financial markets to apply deep reinforcement learning</u></a> [9th India Finance Conference, IIM-A]', abstract: 'In this paper we explore the usage of deep reinforcement learning algorithms to automatically generate consistently profitable, robust, uncorrelated trading signals in any general financial market. In order to do this, we present a novel Markov decision process (MDP) model to capture the financial trading markets. We review and propose various modifications to existing approaches and explore different techniques like the usage of technical indicators, to succinctly capture the market dynamics to model the markets. We then go on to use deep reinforcement learning to enable the agent (the algorithm) to learn how to take profitable trades in any market on its own, while suggesting various methodology changes and leveraging the unique representation of the FMDP (financial MDP) to tackle the primary challenges faced in similar works. Through our experimentation results, we go on to show that our model could be easily extended to two very different financial markets and generates a positively robust performance in all conducted experiments.' },
];

const PREPRINTS: Publication[] = [
  { citation: 'Dianbo Liu, <b>Vedant Shah</b>, Oussama Boussif, Cristian Meo, Anirudh Goyal, Tianmin Shu, Michael Mozer, Nicolas Heess, Yoshua Bengio (2022). <a href="https://arxiv.org/abs/2205.10607"><u>Coordinating Policies Among Multiple Agents via an Intelligent Communication Channel</u></a> [arXiv]', abstract: 'In Multi-Agent Reinforcement Learning (MARL), specialized channels are often introduced that allow agents to communicate directly with one another. In this paper, we propose an alternative approach whereby agents communicate through an intelligent facilitator that learns to sift through and interpret signals provided by all agents to improve the agents\' collective performance. To ensure that this facilitator does not become a centralized controller, agents are incentivized to reduce their dependence on the messages it conveys, and the messages can only influence the selection of a policy from a fixed set, not instantaneous actions given the policy. We demonstrate the strength of this architecture over existing baselines on several cooperative MARL environments.' },
  { citation: 'Yaman Singla Kumar*, Swapnil Parekh*, <b>Somesh Singh</b>*, Junyi Jessy Li, Rajiv Ratn Shah, Changyou Chen (2021). <a href="https://arxiv.org/abs/2109.11728"><u>AES Systems Are Both Overstable And Oversensitive</u></a> [arXiv]', abstract: 'Deep-learning based Automatic Essay Scoring (AES) systems are being actively used by states and language testing agencies alike to evaluate millions of candidates for life-changing decisions ranging from college applications to visa approvals. However, little research has been put to understand and interpret the black-box nature of deep-learning based scoring algorithms. Previous studies indicate that scoring models can be easily fooled. In this paper, we explore the reason behind their surprising adversarial brittleness. We utilize recent advances in interpretability to find the extent to which features such as coherence, content, vocabulary, and relevance are important for automated scoring mechanisms. We use this to investigate the oversensitivity i.e., large change in output score with a little change in input essay content) and overstability i.e., little change in output scores with large changes in input essay content) of AES. Our results indicate that autoscoring models, despite getting trained as "end-to-end" models with rich contextual embeddings such as BERT, behave like bag-of-words models. A few words determine the essay score without the requirement of any context making the model largely overstable. This is in stark contrast to recent probing studies on pre-trained representation learning models, which show that rich linguistic features such as parts-of-speech and morphology are encoded by them. Further, we also find that the models have learnt dataset biases, making them oversensitive. To deal with these issues, we propose detection-based protection models that can detect oversensitivity and overstability causing samples with high accuracies. We find that our proposed models are able to detect unusual attribution patterns and flag adversarial samples successfully.' },
  { citation: 'Arijit Gupta, <b>Rajaswa Patil</b>, Veeky Baths (2021). <a href="https://arxiv.org/abs/2105.05091"><u>Using Diachronic Distributed Word Representations as Models of Lexical Development in Children</u></a> [arXiv]', abstract: 'Recent work has shown that distributed word representations can encode abstract semantic and syntactic information from child-directed speech. In this paper, we use diachronic distributed word representations to perform temporal modeling and analysis of lexical development in children. Unlike all previous work, we use temporally sliced speech corpus to learn distributed word representations of child and child-directed speech. Through our modeling experiments, we demonstrate the dynamics of growing lexical knowledge in children over time, as compared against a saturated level of lexical knowledge in child-directed adult speech. We also fit linear mixed-effects models with the rate of semantic change in the diachronic representations and word frequencies. This allows us to inspect the role of word frequencies towards lexical development in children. Further, we perform a qualitative analysis of the diachronic representations from our model, which reveals the categorization and word associations in the mental lexicon of children.' },
  { citation: '<b>Pranav Mahajan</b>, Advait Rane, Swapna Sasi, Basabdatta Sen Bhattacharya (2021). <a href="https://arxiv.org/abs/2012.06112"><u>Quantifying Synchronization in a Biologically Inspired Neural Network</u></a> [arXiv]', abstract: 'We present a collated set of algorithms to obtain objective measures of synchronisation in brain time-series data. The algorithms are implemented in MATLAB; we refer to our collated set of \'tools\' as SyncBox. Our motivation for SyncBox is to understand the underlying dynamics in an existing population neural network, commonly referred to as neural mass models, that mimic Local Field Potentials of the visual thalamic tissue. Specifically, we aim to measure the phase synchronisation objectively in the model response to periodic stimuli; this is to mimic the condition of Steady-state-visually-evoked-potentials (SSVEP), which are scalp Electroencephalograph (EEG) corresponding to periodic stimuli. We showcase the use of SyncBox on our existing neural mass model of the visual thalamus. Following our successful testing of SyncBox, it is currently being used for further research on understanding the underlying dynamics in enhanced neural networks of the visual pathway.' },
  { citation: '<b>Het Shah</b>, <b>Avishree Khare</b>*, <b>Neelay Shah</b>*, Khizir Siddiqui*. (2020). <a href="https://arxiv.org/pdf/2011.14691.pdf"><u>KD-Lib: A PyTorch library for Knowledge Distillation, Pruning and Quantization</u></a> [arXiv]', abstract: 'In recent years, the growing size of neural networks has led to a vast amount of research concerning compression techniques to mitigate the drawbacks of such large sizes. Most of these research works can be categorized into three broad families : Knowledge Distillation, Pruning, and Quantization. While there has been steady research in this domain, adoption and commercial usage of the proposed techniques has not quite progressed at the rate. We present KD-Lib, an open-source PyTorch based library, which contains state-of-the-art modular implementations of algorithms from the three families on top of multiple abstraction layers. KD-Lib is model and algorithm-agnostic, with extended support for hyperparameter tuning using Optuna and Tensorboard for logging and monitoring. The library can be found at - https://github.com/SforAiDl/KD_Lib' },
  { citation: 'Megh Thakkar, <b>Vishwa Shah</b>, Ramit Sawhney and Debdoot Mukherjee (2021). <b><u>Sequence Mixup for Zero-Shot Cross-Lingual Part-Of-Speech Tagging</u></b> [Extended Abstract, MRL Workshop, EMNLP 2021]', abstract: 'There have been efforts in cross-lingual transfer learning for various tasks. We present an approach utilizing an interpolative data augmentation method, Mixup, to improve the generalizability of models for part-of-speech tagging trained on a source language, improving its performance on unseen target languages. Through experiments on ten languages with diverse structures and language roots, we put forward its applicability for downstream zeroshot cross-lingual tasks.' },
];

function PaperCard({ pub }: { pub: Publication }) {
  const [open, setOpen] = useState(false);
  const hasAbstract = !!pub.abstract;

  return (
    <div className={`${styles.paper} ${open ? styles.paperOpen : ""}`}>
      <div
        className={`${styles.paperTop} ${hasAbstract ? styles.paperClickable : ""}`}
        onClick={(e) => {
          if (!hasAbstract) return;
          // Don't toggle if user clicked an actual link
          if ((e.target as HTMLElement).tagName === "A") return;
          setOpen(!open);
        }}
        role={hasAbstract ? "button" : undefined}
        tabIndex={hasAbstract ? 0 : undefined}
        onKeyDown={(e) => {
          if (hasAbstract && (e.key === "Enter" || e.key === " ")) {
            e.preventDefault();
            setOpen(!open);
          }
        }}
      >
        <div
          className={styles.paperCitation}
          dangerouslySetInnerHTML={{ __html: pub.citation }}
        />
        {hasAbstract && (
          <span className={styles.toggleIcon}>
            {open ? "▲" : "▼"}
          </span>
        )}
      </div>
      <div className={`${styles.abstractWrapper} ${open && pub.abstract ? styles.open : ""}`}>
        <div className={styles.abstractInner}>
          <div className={styles.abstract}>
            <div className={styles.abstractTitle}>Abstract</div>
            <p>{pub.abstract}</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default function PublicationsPage() {
  return (
    <main className={styles.main}>
      <FadeIn>
        <div className={styles.sectionLabel}>
          <span className={styles.labelDot} />
          PUBLICATIONS
        </div>
      </FadeIn>

      <div className={styles.list}>
        {PUBLICATIONS.map((pub, i) => (
          <PaperCard key={i} pub={pub} />
        ))}
      </div>

      <FadeIn>
        <div className={`${styles.sectionLabel} ${styles.preprintLabel}`}>
          <span className={styles.labelDot} />
          PREPRINTS
        </div>
      </FadeIn>

      <div className={styles.list}>
        {PREPRINTS.map((pub, i) => (
          <PaperCard key={i} pub={pub} />
        ))}
      </div>
    </main>
  );
}
